use civ6_autotest_rs::growth_sync::{compare, Checkpoint, UnitKey};

// Independent collector fixtures, not output generated by the parser under test.
const HOST: &str = "12|0|0~10~3~20~bold~leader~blade,cloak~relic~12|0~11~1~0~calm~guard~~none~-1|1~10~2~4~wise~scout~bow~none~11|1~21~30~125~brave~fighter~spear,armor~seal~12";
const PEER: &str = "12|1|1~21~30~1.25e2~brave~fighter~spear,armor~seal~12|0~11~1~0.0~calm~guard~~none~-1|1~10~2~4.0~wise~scout~bow~none~11|0~10~3~20.0~bold~leader~blade,cloak~relic~12";

fn captures() -> (Checkpoint, Checkpoint) {
    (
        Checkpoint {
            endpoint_id: "host-machine".into(),
            session_tag: "lan-session-a".into(),
            barrier_tag: "growth-boundary-12".into(),
            phase: "after-growth".into(),
            observation: HOST.into(),
        },
        Checkpoint {
            endpoint_id: "join-machine".into(),
            session_tag: "lan-session-a".into(),
            barrier_tag: "growth-boundary-12".into(),
            phase: "after-growth".into(),
            observation: PEER.into(),
        },
    )
}

// Mutate only one peer record, always the key owner=0/unitID=10.
fn change_field(peer: &mut Checkpoint, field: usize, value: &str) {
    let mut rows: Vec<String> = peer.observation.split('|').map(str::to_owned).collect();
    let mut columns: Vec<String> = rows[5].split('~').map(str::to_owned).collect();
    assert_eq!(&columns[..2], ["0", "10"]);
    columns[field] = value.into();
    rows[5] = columns.join("~");
    peer.observation = rows.join("|");
}

fn rejects(left: &Checkpoint, right: &Checkpoint, expected: &[&str]) {
    let before = (left.clone(), right.clone());
    let message = compare(left, right).unwrap_err().to_string();
    for fragment in expected {
        assert!(
            message.contains(fragment),
            "expected {fragment:?}: {message}"
        );
    }
    assert_eq!((left, right), (&before.0, &before.1), "raw inputs changed");
}

#[test]
fn independent_endpoints_allow_player_difference_row_order_and_lua_xp_notation() {
    let (left, right) = captures();
    let before = (left.clone(), right.clone());
    compare(&left, &right).unwrap();
    compare(&right, &left).unwrap();
    let parsed = right.parse().unwrap();
    assert_eq!(parsed.world_turn, 12);
    assert_eq!(parsed.local_player, 1);
    assert_eq!(parsed.records.len(), 4);
    assert_eq!(
        parsed.records[0].key,
        UnitKey {
            owner: 0,
            unit_id: 10
        }
    );
    assert_eq!(parsed.records[0].xp, 20.0);
    assert_eq!(parsed.records[1].equipment, "");
    assert_eq!(parsed.records[1].last_xp_turn, -1);
    assert_eq!(
        parsed.records[2].key,
        UnitKey {
            owner: 1,
            unit_id: 10
        }
    );
    assert_eq!(parsed.records[3].level, 30);
    assert_eq!((left, right), before);
}

#[test]
fn captured_hotseat_rows_keep_real_unit_ids_and_growth_fields() {
    // From the first real hotseat handoff in live run 16. The second endpoint
    // and its player field are synthetic: this checks the row contract only.
    const OBSERVED: &str = "1|1|0~65536~1~20~JAC_PERSONALITY_BRAVE~JAC_TRAIT_VALIANT~JAC_ITEM_POC_BLADE,JAC_ITEM_POC_CLOAK~JAC_ARTIFACT_POC_RELIC~1|0~131073~1~20~JAC_PERSONALITY_CALM~JAC_TRAIT_FIERCE~JAC_ITEM_POC_BLADE~none~1|1~65536~1~20~JAC_PERSONALITY_BRAVE~JAC_TRAIT_VALIANT~JAC_ITEM_POC_BLADE,JAC_ITEM_POC_CLOAK~JAC_ARTIFACT_POC_RELIC~1|1~131073~1~20~JAC_PERSONALITY_CALM~JAC_TRAIT_FIERCE~JAC_ITEM_POC_BLADE~none~1";
    let (mut host, mut peer) = captures();
    host.observation = OBSERVED.replacen("1|1|", "1|0|", 1);
    peer.observation = OBSERVED.into();
    compare(&host, &peer).unwrap();
    let parsed = peer.parse().unwrap();
    assert_eq!(parsed.records.len(), 4);
    assert_eq!(
        parsed.records[0].key,
        UnitKey {
            owner: 0,
            unit_id: 65536
        }
    );
    assert_eq!(
        parsed.records[3].key,
        UnitKey {
            owner: 1,
            unit_id: 131073
        }
    );
    assert_eq!(
        parsed.records[0].equipment,
        "JAC_ITEM_POC_BLADE,JAC_ITEM_POC_CLOAK"
    );
    assert_eq!(parsed.records[3].artifact, "none");
    assert_eq!(parsed.records[3].last_xp_turn, 1);
}

#[test]
fn identical_endpoint_is_rejected_even_with_different_players() {
    let (left, mut right) = captures();
    right.endpoint_id = left.endpoint_id.clone();
    rejects(&left, &right, &["endpoint_id", "must differ"]);
}

#[test]
fn blank_endpoint_is_rejected_on_either_side() {
    let (left, right) = captures();
    for blank in ["", " \t", "bad\nendpoint"] {
        let mut bad = right.clone();
        bad.endpoint_id = blank.into();
        rejects(&left, &bad, &["endpoint_id"]);
        rejects(&bad, &left, &["endpoint_id"]);
    }
}

macro_rules! tag_difference {
    ($name:ident, $field:ident) => {
        #[test]
        fn $name() {
            let (left, mut right) = captures();
            right.$field = "different".into();
            rejects(&left, &right, &[stringify!($field), "left=", "right="]);
        }
    };
}
tag_difference!(different_session_is_rejected, session_tag);
tag_difference!(different_barrier_is_rejected, barrier_tag);
tag_difference!(different_phase_is_rejected, phase);

#[test]
fn absent_collection_tags_are_rejected() {
    let (left, right) = captures();
    for field in ["session_tag", "barrier_tag", "phase"] {
        let mut bad = right.clone();
        match field {
            "session_tag" => bad.session_tag.clear(),
            "barrier_tag" => bad.barrier_tag.clear(),
            _ => bad.phase.clear(),
        }
        rejects(&left, &bad, &[field]);
    }
}

#[test]
fn different_world_turn_is_rejected() {
    let (left, mut right) = captures();
    right.observation = PEER.replacen("12|1|", "13|1|", 1);
    rejects(&left, &right, &["worldTurn", "left=12", "right=13"]);
}

#[test]
fn endpoints_must_operate_different_players() {
    let (left, mut right) = captures();
    right.observation = PEER.replacen("12|1|", "12|0|", 1);
    rejects(&left, &right, &["localPlayer", "different players"]);
}

macro_rules! record_difference {
    ($name:ident, $index:expr, $value:expr, $field:expr) => {
        #[test]
        fn $name() {
            let (left, mut right) = captures();
            change_field(&mut right, $index, $value);
            rejects(
                &left,
                &right,
                &["owner=0 unitID=10", $field, "left=", "right="],
            );
        }
    };
}
record_difference!(different_level_is_rejected, 2, "4", "level");
record_difference!(different_xp_is_rejected, 3, "21", "XP");
record_difference!(different_last_xp_turn_is_rejected, 8, "11", "LastXPTurn");
record_difference!(different_personality_is_rejected, 4, "calm", "personality");
record_difference!(different_trait_is_rejected, 5, "guard", "trait");
record_difference!(
    different_equipment_is_rejected,
    6,
    "blade,armor",
    "equipment"
);
record_difference!(
    reordered_equipment_is_rejected,
    6,
    "cloak,blade",
    "equipment"
);
record_difference!(different_artifact_is_rejected, 7, "none", "artifact");
record_difference!(
    string_whitespace_is_not_normalized,
    4,
    "bold ",
    "personality"
);

#[test]
fn changed_unit_id_reports_missing_and_extra_keys() {
    let (left, mut right) = captures();
    change_field(&mut right, 1, "99");
    rejects(
        &left,
        &right,
        &[
            "owner/unitID keys",
            "missing",
            "unit_id: 10",
            "extra",
            "unit_id: 99",
        ],
    );
}

#[test]
fn changed_owner_is_rejected_with_owner_and_observed_keys() {
    let (left, mut right) = captures();
    // Change only the owner of unit 11; its other fields remain untouched.
    right.observation = right.observation.replace("0~11~1~", "1~11~1~");
    rejects(&left, &right, &["owner=0.records", "got 1", "unit_id: 10"]);
}

#[test]
fn balanced_owner_corruption_reports_key_difference() {
    let (left, mut right) = captures();
    right.observation = right.observation.replace("1~21~30~", "0~21~30~");
    right.observation = right.observation.replace("0~11~1~", "1~11~1~");
    rejects(
        &left,
        &right,
        &[
            "owner/unitID keys",
            "missing",
            "extra",
            "owner: 0",
            "unit_id: 11",
        ],
    );
}

#[test]
fn duplicate_key_is_rejected_on_either_endpoint() {
    let (left, mut right) = captures();
    change_field(&mut right, 1, "11");
    rejects(&left, &right, &["owner=0 unitID=11", "duplicate"]);
    rejects(&right, &left, &["owner=0 unitID=11", "duplicate"]);
}

#[test]
fn missing_record_is_rejected_on_either_endpoint() {
    let (left, mut right) = captures();
    right.observation = PEER.rsplit_once('|').unwrap().0.into();
    rejects(&left, &right, &["owner=0.records", "expected 2, got 1"]);
    rejects(&right, &left, &["owner=0.records", "expected 2, got 1"]);
}

#[test]
fn extra_unique_record_is_rejected() {
    let (left, mut right) = captures();
    right.observation.push_str("|0~99~1~0~bold~leader~~none~-1");
    rejects(&left, &right, &["owner=0.records", "got 3", "unit_id: 99"]);
}

macro_rules! invalid_field {
    ($name:ident, $index:expr, $field:expr, [$($value:expr),+ $(,)?]) => {
        #[test]
        fn $name() {
            let (left, right) = captures();
            for value in [$($value),+] {
                let mut bad = right.clone();
                change_field(&mut bad, $index, value);
                rejects(&left, &bad, &[$field, "unitID="]);
                rejects(&bad, &left, &[$field, "unitID="]);
            }
        }
    };
}
invalid_field!(
    invalid_owner_is_rejected,
    0,
    "owner",
    ["-1", "2", "x", "0.5"]
);
invalid_field!(
    invalid_unit_id_is_rejected,
    1,
    "unitID",
    ["-1", "x", "10.5", "9223372036854775808"]
);
invalid_field!(
    invalid_level_is_rejected,
    2,
    "level",
    ["0", "31", "-1", "2.5", "x", ""]
);
invalid_field!(negative_xp_is_rejected, 3, "XP", ["-1", "-0.01"]);
invalid_field!(fractional_xp_is_rejected, 3, "XP", ["4.5", "1.25e1"]);
invalid_field!(
    nonfinite_xp_is_rejected,
    3,
    "XP",
    ["NaN", "inf", "-inf", "1e309"]
);
invalid_field!(
    malformed_xp_is_rejected,
    3,
    "XP",
    ["", "x", "20 XP", " 20", "0x14"]
);
invalid_field!(
    invalid_last_xp_turn_is_rejected,
    8,
    "LastXPTurn",
    ["-2", "13", "12.5", "x", ""]
);
invalid_field!(
    invalid_personality_is_rejected,
    4,
    "personality",
    ["", " ", "bold\n"]
);
invalid_field!(invalid_trait_is_rejected, 5, "trait", ["", "guard\r"]);
invalid_field!(
    invalid_equipment_is_rejected,
    6,
    "equipment",
    ["blade,", ",blade", "blade,,cloak", "blade\n"]
);
invalid_field!(invalid_artifact_is_rejected, 7, "artifact", ["", "none\t"]);

#[test]
fn malformed_world_turn_is_rejected() {
    let (left, right) = captures();
    for value in ["", "-1", "x", "12.5", "9223372036854775808"] {
        let mut bad = right.clone();
        bad.observation = PEER.replacen("12|", &format!("{value}|"), 1);
        rejects(&left, &bad, &["worldTurn"]);
    }
}

#[test]
fn malformed_local_player_is_rejected() {
    let (left, right) = captures();
    for value in ["", "-1", "2", "x", "0.5"] {
        let mut bad = right.clone();
        bad.observation = PEER.replacen("12|1|", &format!("12|{value}|"), 1);
        rejects(&left, &bad, &["localPlayer"]);
    }
}

#[test]
fn malformed_row_shape_is_rejected() {
    let (left, right) = captures();
    for row in ["0~10~3~20", "0~10~3~20~bold~leader~~none~12~extra", ""] {
        let mut bad = right.clone();
        bad.observation = format!("{}|{row}", PEER.rsplit_once('|').unwrap().0);
        rejects(&left, &bad, &["record[4]", "expected 9 fields"]);
    }
}

#[test]
fn malformed_or_empty_observation_is_rejected() {
    let (left, right) = captures();
    for (raw, field) in [
        ("", "worldTurn"),
        ("12", "localPlayer"),
        ("12|1", "owner=0.records"),
    ] {
        let mut bad = right.clone();
        bad.observation = raw.into();
        rejects(&left, &bad, &[field]);
    }
}

#[test]
fn serialized_checkpoint_retains_raw_observation_and_still_requires_validation() {
    let (left, right) = captures();
    let serialized = serde_json::to_string(&right).unwrap();
    let decoded: Checkpoint = serde_json::from_str(&serialized).unwrap();
    assert_eq!(decoded, right);
    compare(&left, &decoded).unwrap();
    // Serialization is only an envelope round trip, not a game save/reload test.
    let mut bad = decoded;
    change_field(&mut bad, 3, "NaN");
    let bad: Checkpoint = serde_json::from_str(&serde_json::to_string(&bad).unwrap()).unwrap();
    rejects(&left, &bad, &["XP"]);
}
